  background: var(--surface);
  color: var(--text-h);
  font-weight: 600;
  text-decoration: none;
  transition: transform 0.1s, box-shadow 0.1s;
}

.card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
  border-color: var(--accent);
}

.card img {
  width: 100%;
  aspect-ratio: 1;
  object-fit: contain;
}

.detail {
  border: 1px solid var(--border);
  border-radius: 18px;
  background: var(--surface);
  padding: 20px;
}

.pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}

.arrow {
  padding: 8px 16px;
  border-radius: 10px;
  border: 1px solid var(--border);
  color: var(--text-h);
  font-weight: 600;
  text-decoration: none;
}

.arrow:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.position {
  font-family: var(--mono);
  font-size: 0.85rem;
}

.body {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  align-items: flex-start;
}

.art {
  flex: 1 1 260px;
  max-width: 360px;
  aspect-ratio: 1;
  object-fit: contain;
  margin: 0 auto;
}

.info {
  flex: 1 1 300px;
}

.info h1 {
  margin: 0 0 8px;
  color: var(--text-h);
}

.info h2 {
  font-size: 1.1rem;
  color: var(--text-h);
  margin: 20px 0 8px;
}

.number {
  margin: 0;
  font-family: var(--mono);
}

.types {
  display: flex;
  gap: 6px;
}

.facts {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 6px 16px;
  margin: 16px 0 0;
}

.facts dt {
  font-weight: 600;
  color: var(--text-h);
}

.facts dd {
  margin: 0;
}

.stats {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stats li {
  display: grid;
  grid-template-columns: 130px 1fr 40px;
  align-items: center;
  gap: 10px;
}

.stats meter {
  width: 100%;
}

.statName {
  text-transform: capitalize;
}

.statValue {
  text-align: right;
  font-family: var(--mono);
}

.missing {
  text-align: center;
  padding: 40px 0;
}

